<?php
include '../config.php';
if(empty($_SESSION['admin'])){header('Location: login.php');exit;}
if(isset($_POST['delete_resume'])){ $id=(int)$_POST['id']; $s=$conn->prepare('DELETE FROM resumes WHERE id=?'); $s->bind_param('i',$id); $s->execute(); }
if(isset($_POST['delete_user'])){ $id=(int)$_POST['id']; $s=$conn->prepare('DELETE FROM users WHERE id=?'); $s->bind_param('i',$id); $s->execute(); }
$users=$conn->query('SELECT id,name,email,created_at FROM users ORDER BY id DESC');
$resumes=$conn->query('SELECT r.*,u.name AS user_name,u.email AS user_email FROM resumes r LEFT JOIN users u ON u.id=r.user_id ORDER BY r.updated_at DESC');
$uc=(int)$conn->query('SELECT COUNT(*) c FROM users')->fetch_assoc()['c'];
$rc=(int)$conn->query('SELECT COUNT(*) c FROM resumes')->fetch_assoc()['c'];
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Dashboard — ResumeFlow</title><link rel="stylesheet" href="../assets/css/app.css"></head><body><header class="topbar appbar"><a class="brand" href="../index.php"><span class="brand-mark">R</span> ResumeFlow <small>ADMIN</small></a><nav><a class="active" href="<?php echo e(admin_tab_url('dashboard.php')); ?>">Dashboard</a><a class="nav-btn" href="<?php echo e(admin_tab_url('logout.php')); ?>">Log out</a></nav></header><main class="page"><div class="welcome"><div><span class="eyebrow">ADMIN CONTROL CENTER</span><h1>Manage your resume platform.</h1><p>View accounts and resume activity from a separate protected area.</p></div></div><div class="stat-grid"><div class="stat panel"><span>USERS</span><b><?php echo $uc; ?></b></div><div class="stat panel"><span>RESUMES</span><b><?php echo $rc; ?></b></div></div><section class="panel admin-table"><div class="panel-title"><div><span class="muted">ACCOUNTS</span><h2>Registered users</h2></div></div><div class="table-scroll"><table><tr><th>ID</th><th>Name</th><th>Email</th><th>Joined</th><th></th></tr><?php while($u=$users->fetch_assoc()): ?><tr><td><?php echo $u['id']; ?></td><td><b><?php echo e($u['name']); ?></b></td><td><?php echo e($u['email']); ?></td><td><?php echo e($u['created_at']); ?></td><td><form method="post" onsubmit="return confirm('Delete this user and their resume?')"><input type="hidden" name="id" value="<?php echo $u['id']; ?>"><button class="danger" name="delete_user">Delete</button></form></td></tr><?php endwhile; ?></table></div></section><section class="panel admin-table"><div class="panel-title"><div><span class="muted">RESUMES</span><h2>Created resumes</h2></div></div><div class="table-scroll"><table><tr><th>Name</th><th>Account</th><th>Region</th><th>Updated</th><th></th></tr><?php while($x=$resumes->fetch_assoc()): ?><tr><td><b><?php echo e($x['full_name']?:'Untitled'); ?></b><br><small><?php echo e($x['headline']); ?></small></td><td><?php echo e($x['user_email']); ?></td><td><span class="badge"><?php echo e(strtoupper($x['region']??'india')); ?></span></td><td><?php echo e($x['updated_at']); ?></td><td><a class="small-action" href="<?php echo e(admin_tab_url('preview.php?id='.$x['id'])); ?>">View</a> <form class="inline" method="post" onsubmit="return confirm('Delete this resume?')"><input type="hidden" name="id" value="<?php echo $x['id']; ?>"><button class="danger" name="delete_resume">Delete</button></form></td></tr><?php endwhile; ?></table></div></section></main><script src="../assets/js/admin-tab-auth.js"></script></body></html>
